<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { Plus, Search, UserRound, UsersRound, Gem, UserMinus, AlertTriangle, CheckCircle2 } from '@lucide/vue'
import { api } from '../../services/api';import { authStore } from '../../stores/auth';import { uiStore } from '../../stores/ui';import { money, positionName } from '../../utils'
import PageHeader from '../../components/PageHeader.vue';import LoadingBlock from '../../components/LoadingBlock.vue';import EmptyState from '../../components/EmptyState.vue';import EntityAvatar from '../../components/EntityAvatar.vue';import StatusBadge from '../../components/StatusBadge.vue';import BaseModal from '../../components/BaseModal.vue';import PaginationBar from '../../components/PaginationBar.vue'
const isAdmin=computed(()=>authStore.isAdmin.value),tab=ref('players'),loading=ref(true),rows=ref([]),clubs=ref([]),seasons=ref([]),rosterStatus=ref(null),meta=ref({page:1,limit:20,total:0}),filters=ref({search:'',position:'',status:''}),modal=ref(''),busy=ref(false),selected=ref(null),form=ref({});let debounce
function resetPlayer(){form.value={full_name:'',position:'FW',shirt_number:'',club_id:isAdmin.value?'':authStore.user.value.clubId,market_value:'0',photo_url:'',contract:{start_season_id:'',end_season_id:'',salary_per_season:'0',note:''}}}
function resetStaff(){form.value={full_name:'',staff_role:'Huấn luyện viên trưởng',club_id:isAdmin.value?'':authStore.user.value.clubId,contract:{start_season_id:'',end_season_id:'',salary_per_season:'0',note:''}}}
async function loadRosterStatus(){if(isAdmin.value||!authStore.user.value?.clubId){rosterStatus.value=null;return}try{rosterStatus.value=(await api.get(`/clubs/${authStore.user.value.clubId}/roster-status`)).data}catch{rosterStatus.value=null}}
async function load(page=1){loading.value=true;try{const path=tab.value==='players'?'/players':'/staff';const query=tab.value==='players'?{page,limit:20,...filters.value}:{page,limit:20};const r=await api.get(path,query);rows.value=r.data;meta.value=r.meta}catch(e){uiStore.notify(e.message,'error')}finally{loading.value=false}}
watch([tab,filters],()=>{clearTimeout(debounce);debounce=setTimeout(()=>load(1),250)},{deep:true});onMounted(async()=>{try{const [c,s]=await Promise.all([isAdmin.value?api.get('/clubs',{limit:100,status:'APPROVED'}):Promise.resolve({data:[]}),api.get('/seasons')]);clubs.value=c.data;seasons.value=s.data}catch{}await Promise.all([load(),loadRosterStatus()])})
function openCreate(){selected.value=null;if(tab.value==='players')resetPlayer();else resetStaff();modal.value=tab.value}
function openEdit(row){selected.value=row;form.value={...row};modal.value=tab.value}
async function save(){
  busy.value=true
  try{
    const source=JSON.parse(JSON.stringify(form.value))
    if(tab.value==='players'){
      if(selected.value){
        const payload={full_name:source.full_name,position:source.position,shirt_number:source.shirt_number,photo_url:source.photo_url,status:source.status}
        await api.patch(`/players/${selected.value.id}`,payload)
      }else{
        if(!source.club_id) delete source.contract
        await api.post('/players',source)
      }
    }else{
      if(selected.value){
        const payload={full_name:source.full_name,staff_role:source.staff_role,status:source.status}
        await api.patch(`/staff/${selected.value.id}`,payload)
      }else{
        if(!source.club_id) delete source.contract
        await api.post('/staff',source)
      }
    }
    uiStore.notify('Đã lưu dữ liệu.');modal.value='';await Promise.all([load(meta.value.page),loadRosterStatus()])
  }catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}
}
async function updateValue(row){const value=window.prompt(`Giá trị mới cho ${row.full_name}`,String(row.market_value||0));if(value===null)return;const reason=window.prompt('Lý do thay đổi giá','Admin FIFA cập nhật theo mùa giải');if(!reason)return;try{await api.post(`/players/${row.id}/market-value`,{new_value:value,reason});uiStore.notify('Đã cập nhật giá cầu thủ.');load(meta.value.page)}catch(e){uiStore.notify(e.message,'error')}}
async function release(row){const reason=window.prompt(`Lý do thanh lý ${row.full_name}`,'Thanh lý hợp đồng theo quyết định CLB');if(!reason)return;try{await api.post(`/players/${row.id}/release`,{reason});uiStore.notify('Cầu thủ đã trở thành tự do.');await Promise.all([load(meta.value.page),loadRosterStatus()])}catch(e){uiStore.notify(e.message,'error')}}
</script>
<template><div><PageHeader eyebrow="Squad & Staff" :title="isAdmin?'Quản lý cầu thủ và ban huấn luyện':'Đội hình câu lạc bộ'" description="Hồ sơ tối giản, tập trung vào vị trí, số áo, lương, giá trị và trạng thái hiện tại."><button class="btn btn-primary" @click="openCreate"><Plus :size="17"/>{{ tab==='players'?'Thêm cầu thủ':'Thêm BHL' }}</button></PageHeader><section v-if="!isAdmin&&rosterStatus" class="roster-health" :class="rosterStatus.has_warning?'warning':'ready'"><component :is="rosterStatus.has_warning?AlertTriangle:CheckCircle2" :size="24"/><div><b>{{ rosterStatus.has_warning?'Đội hình cố định chưa đủ người':'Đội hình cố định đã sẵn sàng' }}</b><p>{{ rosterStatus.active_count }}/{{ rosterStatus.minimum_required }} cầu thủ hoạt động<span v-if="rosterStatus.has_warning"> · cần thêm {{ rosterStatus.shortage_count }} cầu thủ</span>. Khi FIFA thêm CLB vào giải, toàn bộ danh sách này sẽ được đăng ký tự động.</p></div></section><div class="tabs"><button class="btn" :class="{active:tab==='players'}" @click="tab='players'"><UserRound :size="17"/>Cầu thủ</button><button class="btn" :class="{active:tab==='staff'}" @click="tab='staff'"><UsersRound :size="17"/>Ban huấn luyện</button></div><div v-if="tab==='players'" class="glass card toolbar"><div class="toolbar-actions"><div class="search"><Search :size="17"/><input v-model="filters.search" class="input" placeholder="Tìm cầu thủ..."/></div><select v-model="filters.position" class="select"><option value="">Tất cả vị trí</option><option value="GK">Thủ môn</option><option value="DF">Hậu vệ</option><option value="MF">Tiền vệ</option><option value="FW">Tiền đạo</option></select><select v-model="filters.status" class="select"><option value="">Tất cả trạng thái</option><option value="ACTIVE">Đang thi đấu</option><option value="FREE_AGENT">Tự do</option><option value="TRANSFER_LISTED">Rao bán</option><option value="SUSPENDED">Tạm khóa</option></select></div><span class="muted">{{ meta.total }} cầu thủ</span></div><LoadingBlock v-if="loading"/><EmptyState v-else-if="!rows.length"/><div v-else class="glass card table-card"><div class="table-wrap"><table><thead><tr v-if="tab==='players'"><th>Cầu thủ</th><th>CLB</th><th>Vị trí</th><th>Số áo</th><th>Lương/mùa</th><th>Giá trị</th><th>Trạng thái</th><th></th></tr><tr v-else><th>Thành viên</th><th>CLB</th><th>Chức vụ</th><th>Lương/mùa</th><th>Số dư</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><template v-if="tab==='players'"><td><div class="entity"><EntityAvatar :src="row.photo_url" :name="row.full_name" :size="40" round/><span class="entity-name">{{ row.full_name }}</span></div></td><td>{{ row.club_name||'Tự do' }}</td><td>{{ positionName(row.position) }}</td><td><b>#{{ row.shirt_number||'—' }}</b></td><td>{{ money(row.salary_per_season,true) }}</td><td><b>{{ money(row.market_value,true) }}</b></td><td><StatusBadge :status="row.status"/></td><td><div class="actions"><button class="btn btn-sm" @click="selected=row;form={...row};modal='players'">Sửa</button><button v-if="isAdmin" class="btn btn-sm" @click="updateValue(row)"><Gem :size="14"/>Giá</button><button v-if="row.club_id" class="btn btn-sm btn-danger" @click="release(row)"><UserMinus :size="14"/></button></div></td></template><template v-else><td><div class="entity"><EntityAvatar :name="row.full_name" :size="40" round/><span class="entity-name">{{ row.full_name }}</span></div></td><td>{{ row.club_name||'Tự do' }}</td><td>{{ row.staff_role }}</td><td>{{ money(row.salary_per_season,true) }}</td><td>{{ money(row.wallet_balance,true) }}</td><td><StatusBadge :status="row.status"/></td><td><button class="btn btn-sm" @click="selected=row;form={...row};modal='staff'">Sửa</button></td></template></tr></tbody></table></div><PaginationBar v-bind="meta" @change="load"/></div><BaseModal :open="modal==='players'" :title="selected?'Cập nhật cầu thủ':'Thêm cầu thủ'" @close="modal=''" width="760px"><form class="form-grid" @submit.prevent="save"><label><span class="label">Họ và tên</span><input v-model="form.full_name" class="input" required/></label><label><span class="label">Vị trí</span><select v-model="form.position" class="select"><option value="GK">Thủ môn</option><option value="DF">Hậu vệ</option><option value="MF">Tiền vệ</option><option value="FW">Tiền đạo</option></select></label><label><span class="label">Số áo</span><input v-model="form.shirt_number" type="number" min="1" max="99" class="input"/></label><label v-if="isAdmin&&!selected"><span class="label">CLB</span><select v-model="form.club_id" class="select"><option value="">Cầu thủ tự do</option><option v-for="c in clubs" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label v-if="isAdmin&&!selected"><span class="label">Giá trị ban đầu</span><input v-model="form.market_value" type="number" min="0" class="input"/></label><label class="form-group full"><span class="label">URL ảnh</span><input v-model="form.photo_url" class="input"/></label><label v-if="selected" class="form-group full"><span class="label">Trạng thái</span><select v-model="form.status" class="select"><option value="ACTIVE">Đang thi đấu</option><option value="TRANSFER_LISTED">Rao bán</option><option value="SUSPENDED">Tạm khóa</option><option v-if="isAdmin" value="RETIRED">Giải nghệ</option></select></label><template v-if="!selected&&form.club_id"><label><span class="label">Mùa bắt đầu HĐ</span><select v-model="form.contract.start_season_id" class="select" required><option value="">Chọn mùa</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label><span class="label">Mùa kết thúc HĐ</span><select v-model="form.contract.end_season_id" class="select"><option value="">Không xác định</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label class="form-group full"><span class="label">Lương mỗi mùa</span><input v-model="form.contract.salary_per_season" type="number" min="0" class="input" required/></label></template><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">{{ busy?'Đang lưu...':'Lưu cầu thủ' }}</button></div></form></BaseModal><BaseModal :open="modal==='staff'" :title="selected?'Cập nhật thành viên BHL':'Thêm thành viên BHL'" @close="modal=''" width="650px"><form class="form-grid" @submit.prevent="save"><label><span class="label">Họ và tên</span><input v-model="form.full_name" class="input" required/></label><label><span class="label">Chức vụ</span><input v-model="form.staff_role" class="input" required/></label><label v-if="isAdmin&&!selected"><span class="label">CLB</span><select v-model="form.club_id" class="select"><option value="">Tự do</option><option v-for="c in clubs" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label v-if="selected" class="form-group full"><span class="label">Trạng thái</span><select v-model="form.status" class="select"><option value="ACTIVE">Đang làm việc</option><option value="SUSPENDED">Tạm khóa</option><option value="RETIRED">Nghỉ việc</option></select></label><template v-if="!selected&&form.club_id"><label><span class="label">Mùa bắt đầu</span><select v-model="form.contract.start_season_id" class="select" required><option value="">Chọn mùa</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label class="form-group full"><span class="label">Lương mỗi mùa</span><input v-model="form.contract.salary_per_season" type="number" min="0" class="input"/></label></template><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Lưu</button></div></form></BaseModal></div></template>
<style scoped>.roster-health{display:flex;align-items:center;gap:14px;margin-bottom:16px;padding:15px 17px;border-radius:15px;border:1px solid var(--line)}.roster-health.warning{background:rgba(255,130,100,.08);border-color:rgba(255,130,100,.28);color:#ff9d88}.roster-health.ready{background:rgba(70,225,145,.07);border-color:rgba(70,225,145,.25);color:#68e3a0}.roster-health b{display:block;color:var(--text);margin-bottom:3px}.roster-health p{margin:0;color:var(--muted);font-size:11px}.tabs{display:flex;gap:8px;margin-bottom:16px}.tabs .active{background:linear-gradient(135deg,var(--primary),var(--primary-2));border-color:transparent}.toolbar{margin-bottom:18px;padding:13px}.search{display:flex;align-items:center;gap:7px;min-width:280px}.search .input{border:0;background:transparent;box-shadow:none}.toolbar .select{width:170px}.table-card{padding:0;overflow:hidden}.actions{display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap}.form-group.full.actions{display:flex;justify-content:flex-end;gap:9px}@media(max-width:700px){.search{min-width:100%}.toolbar .select{width:100%}}</style>
